请对以下 case 进行三维加权评分。

=== case_id ===
Case-27-utility-bill-006

=== 用户原始指令 (query.txt) ===
点一下跳app 红色提醒

=== TaskSpec 契约 (task.taskSpec.json) ===
{
  "userQuery": "点一下跳app 红色提醒",
  "size": "2x2",
  "eventCandidates": [
    {
      "call": "clickToDeeplink",
      "args": {
        "bundleName": "com.huawei.hmos.clock",
        "abilityName": "com.huawei.hmos.clock.phone",
        "uri": ""
      }
    }
  ],
  "dataModelSchema": {
    "asset": {
      "primaryIcon": {
        "type": "string",
        "description": "水电缴费提醒主视觉图标资源路径，使用本地电力符号素材。",
        "sampleValue": "resources/base/media/bolt_fill.svg"
      },
      "actionIcon": {
        "type": "string",
        "description": "跳转入口方向图标资源路径，使用本地导航箭头素材。",
        "sampleValue": "resources/base/media/location_north_up_right_fill.svg"
      }
    },
    "primary": {
      "value": {
        "type": "string",
        "description": "水电账单当前提醒状态短文本。",
        "sampleValue": "欠费"
      },
      "caption": {
        "type": "string",
        "description": "服务对象名称。",
        "sampleValue": "水电缴费"
      }
    },
    "support": {
      "title": {
        "type": "string",
        "description": "提醒级别或提醒类型。",
        "sampleValue": "红色提醒"
      },
      "meta": {
        "type": "string",
        "description": "当前提醒的处理状态摘要。",
        "sampleValue": "今日待处理"
      }
    },
    "action": {
      "label": {
        "type": "string",
        "description": "跳转缴费入口的短动作文案。",
        "sampleValue": "去缴费"
      }
    }
  },
  "assetCandidates": [
    {
      "src": "resources/base/media/bolt_fill.svg",
      "description": "闪电实心图标，适合表达用电、水电账单或缴费提醒的主视觉锚点。",
      "bindTo": "/asset/primaryIcon"
    },
    {
      "src": "resources/base/media/location_north_up_right_fill.svg",
      "description": "指向右上方的导航箭头实心图标，适合表达点击跳转或前往应用的动作入口。",
      "bindTo": "/asset/actionIcon"
    }
  ]
}

